using System;using System.Collections.Generic;using System.Linq;using HabitatShift.Core;namespace HabitatShift.LevelLabR10 { [Serializable] public class R10ScrambleStep {public string habitat;public IntPair from,to;} public static class R10ReverseScramble { public static List<R10ScrambleStep> Apply(LevelDto level,int seed,int depth){var r=new List<R10ScrambleStep>();var random=new Random(seed);var mask=new HashSet<string>((level.playableMask??new IntPair[0]).Select(c=>c.x+","+c.y));if(mask.Count==0)for(int x=0;x<level.cols;x++)for(int y=0;y<level.rows;y++)mask.Add(x+","+y);var blocked=new HashSet<string>((level.obstacles??new IntPair[0]).Select(c=>c.x+","+c.y));for(int step=0;step<depth;step++){var h=level.habitats[step%level.habitats.Length];var candidates=new[]{new IntPair{x=h.anchor.x+1,y=h.anchor.y},new IntPair{x=h.anchor.x-1,y=h.anchor.y},new IntPair{x=h.anchor.x,y=h.anchor.y+1},new IntPair{x=h.anchor.x,y=h.anchor.y-1}}.OrderBy(x=>random.Next()).ToArray();var to=candidates.FirstOrDefault(a=>Legal(level,h,a,mask,blocked));if(to==null)continue;var from=h.anchor;h.anchor=to;r.Add(new R10ScrambleStep{habitat=h.id,from=from,to=to});}return r;}static bool Legal(LevelDto l,HabitatDto active,IntPair a,HashSet<string> mask,HashSet<string> blocked){foreach(var q in active.shape){var key=(a.x+q.x)+","+(a.y+q.y);if(!mask.Contains(key)||blocked.Contains(key))return false;foreach(var other in l.habitats)if(other!=active)foreach(var oq in other.shape)if(other.anchor.x+oq.x==a.x+q.x&&other.anchor.y+oq.y==a.y+q.y)return false;}return active.movementConstraint!="HORIZONTAL_ONLY"||a.y==active.anchor.y;} } }
